/**
 * A post card of PostShowcase with the text on a panel over the lower part of the picture: the category and
 * date, the title, the excerpt and a read link.
 */
import { type ReactNode } from "react";
import { Badge, Box, Group, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MediaFrame } from "../components/media-frame";
import { MenuEntry } from "../components/menu-entry";
import { cn } from "../utils";
import type { Post, PostLabels } from "../blocks/post-card.types";

export type PostOverlayCardProps = {
  p: Post;
  labels: PostLabels;
  ratio?: "4/3" | "16/9";
};

export function PostOverlayCard({ p, labels, ratio = "4/3" }: PostOverlayCardProps) {
  return (
    <Box className="relative overflow-hidden rounded" data-testid="post-overlay">
      <MediaFrame alt={p.title} ratio={ratio} className={(((ratio as string) === "4/3") ? "min-h-80" : "min-h-64")} />
      <Stack gap="2" align="start" className="absolute bottom-4 left-4 right-4 rounded bg-background p-4">
        <Group gap="2" align="center">
          <Badge variant="secondary" size="sm">
            {p.category}
          </Badge>
          <Text size="xs" className="text-muted-foreground">
            {p.date}
          </Text>
        </Group>
        <Title as={3} size="base" weight="semibold">
          {p.title}
        </Title>
        <Text size="sm" className={cn("text-muted-foreground", "line-clamp-2")}>
          {p.excerpt}
        </Text>
        <MenuEntry href={p.href} className="gap-2 text-sm font-medium" size="sm" testid="read">
          {labels.read}
          <LucideIcon name="arrow-right" size={16} />
        </MenuEntry>
      </Stack>
    </Box>
  );
}
